/**
 * ThresholdEvaluator - Dynamically evaluates thresholds based on time-of-day.
 * Applies tighter thresholds during business hours (08:00–20:00 local time).
 *
 * Parameters:
 *   $1 - DCI name to check
 *   $2 - business hours threshold (e.g., '80')
 *   $3 - off-hours threshold (e.g., '95')
 */

local node = $node;
local dciName = $1;
local bizThreshold = ($2 != null) ? toInt($2) : 80;
local offThreshold = ($3 != null) ? toInt($3) : 95;

// Determine if we are in business hours (simple UTC hour check)
local hour = toInt(FormatDate(time(), '%H'));
local isBusinessHours = (hour >= 8 && hour < 20);
local threshold = isBusinessHours ? bizThreshold : offThreshold;

local currentValue = toFloat(GetDCIValue(node, dciName));

if (currentValue == null)
  return 'DCI_NOT_FOUND';

if (currentValue >= threshold)
{
  return 'THRESHOLD_EXCEEDED:' + currentValue + '>=' + threshold;
}

return 'OK:' + currentValue + '<' + threshold;
